from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    fg_id = [[-1]*w for _ in range(h)]
    comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or fg_id[r][c] >= 0: continue
            k=len(comps); cells=[]; q=[(r,c)]; fg_id[r][c]=k
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and fg_id[yy][xx]<0:
                        fg_id[yy][xx]=k; q.append((yy,xx))
            comps.append(cells)
    bg_seen=[[False]*w for _ in range(h)]
    holes=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or bg_seen[r][c]: continue
            cells=[]; q=[(r,c)]; bg_seen[r][c]=True; edge=False
            while q:
                y,x=q.pop(); cells.append((y,x))
                if y==0 or y==h-1 or x==0 or x==w-1: edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and not bg_seen[yy][xx]:
                        bg_seen[yy][xx]=True; q.append((yy,xx))
            if not edge: holes.append(cells)
    qualifies=set(); hole_comp=[]
    for hole in holes:
        ids=set()
        for y,x in hole:
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and fg_id[yy][xx]>=0: ids.add(fg_id[yy][xx])
        qualifies |= ids
        hole_comp.append((hole,ids))
    out=[row[:] for row in grid]
    # Color only the inner edge of enclosed regions associated with loop components.
    for hole,ids in hole_comp:
        for y,x in hole:
            if any(0<=y+dy<h and 0<=x+dx<w and fg_id[y+dy][x+dx] in ids
                   for dy in (-1,0,1) for dx in (-1,0,1)):
                out[y][x]=3
    # Add the one-cell Moore-neighborhood halo around qualifying components.
    for k in qualifies:
        for y,x in comps[k]:
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and bg_seen[yy][xx]:
                        # Exterior component: 2. Hole-adjacent cells are colored 3 above.
                        if not any((y0==yy and x0==xx) for hole,_ in hole_comp for y0,x0 in hole):
                            out[yy][xx]=2
    return out
